const G = 9.8;
const LEFT = { mass: 40, arm: 1.5 };
const BEAM = { mass: 10, arm: 0.6, from: -2, to: 3.2 };
const PX = 80;
const PIVOT = [250, 246];
const FLOOR = 336;

figure({
  title: "Seesaw",
  icon: "⚖️",
  level: "9-12",
  mode: "flat",
  size: [780, 380],
  question: "When is a beam in equilibrium?",
  caption:
    "The moment of a force is its turning effect about a pivot: M = F × d, where d is the perpendicular distance from the pivot to the force. Each load's weight is W = mg, with g = 9.8 N/kg. The beam is in equilibrium when the clockwise moments add up to the anticlockwise moments. A uniform beam's weight acts at its centre of mass, here 0.6 m to the right of the pivot.",
  leavesOut:
    "Friction at the pivot, and the small change in perpendicular distance as the beam tilts. The pivot also pushes up with a force equal to the total weight; it has no moment because it acts at the pivot.",
  try: "Switch the beam's weight on, then balance the 40 kg load with a 30 kg load.",
  controls: [
    { id: "mass", label: "Mass of the right load", min: 10, max: 60, step: 5, value: 20, unit: "kg" },
    { id: "arm", label: "Its distance from the pivot", min: 0.5, max: 3, step: 0.1, value: 1.5, unit: "m" },
    { id: "beam", label: "Count the beam's own weight (10 kg)", type: "toggle", value: false },
  ],

  model(s) {
    const round = (value) => Math.round(value * 10) / 10;
    const leftForce = LEFT.mass * G;
    const rightForce = round(s.mass * G);
    const arm = round(s.arm);
    const beamForce = BEAM.mass * G;
    const anticlockwise = round(leftForce * LEFT.arm);
    const load = round(rightForce * arm);
    const beam = s.beam ? round(beamForce * BEAM.arm) : 0;
    const clockwise = round(load + beam);
    const net = round(clockwise - anticlockwise);
    return { leftForce, rightForce, arm, beamForce, anticlockwise, load, beam, clockwise, net, level: Math.abs(net) < 3, tilt: Math.max(-8, Math.min(8, net / 60)) };
  },
  goal: (m, s) => s.beam && m.level && Math.abs(s.mass - 30) < 0.5,
  readout: (m, s) => [
    `Anticlockwise: ${m.leftForce.toFixed(0)} N × ${LEFT.arm} m = ${m.anticlockwise.toFixed(1)} N·m`,
    `Clockwise: ${m.rightForce.toFixed(0)} N × ${m.arm.toFixed(1)} m = ${m.load.toFixed(1)} N·m${s.beam ? `, plus beam ${m.beamForce.toFixed(0)} N × ${BEAM.arm} m = ${m.beam.toFixed(1)} N·m, total ${m.clockwise.toFixed(1)} N·m` : ""}`,
    m.level ? "Equilibrium: the moments are equal." : `Resultant moment ${Math.abs(m.net).toFixed(1)} N·m ${m.net > 0 ? "clockwise" : "anticlockwise"}.`,
  ],

  draw(m, s, f) {
    const [px, py] = PIVOT;
    const turn = (x, y) => {
      const angle = (m.tilt * Math.PI) / 180;
      const dx = x - px;
      const dy = y - py;
      return [px + dx * Math.cos(angle) - dy * Math.sin(angle), py + dx * Math.sin(angle) + dy * Math.cos(angle)];
    };
    const at = (metres) => px + metres * PX;
    const crate = (metres, mass, fill) => {
      const side = 30 + mass * 0.45;
      return [f.rect(at(metres) - side / 2, py - 12 - side, side, side, { r: 6, fill, shadow: true }), f.text(at(metres), py - 20 - side, `${mass.toFixed(0)} kg`, { size: 13, weight: 600 })];
    };
    const weight = (metres, force, label, stroke) => {
      const [x, y] = turn(at(metres), py + 4);
      const length = Math.max(22, force / 15);
      return [f.arrow(x, y, x, y + length, { stroke, head: 8 }), f.text(x, y + length + 15, label, { size: 12, fill: "mid" })];
    };
    const beam = [
      f.rect(at(BEAM.from), py - 12, (BEAM.to - BEAM.from) * PX, 12, { r: 4, fill: "soft", stroke: "edge" }),
      [-1, 1, 2, 3].map((metre) => [f.line(at(metre), py - 12, at(metre), py - 5, { stroke: "mid", width: 1.2 }), f.text(at(metre), py + 15, `${Math.abs(metre)} m`, { size: 11, fill: "mid" })]),
      s.beam ? f.circle(at(BEAM.arm), py - 6, 3.5, { fill: "warm" }) : "",
      crate(-LEFT.arm, LEFT.mass, "cool"),
      crate(s.arm, s.mass, "accent"),
    ];
    const bar = (x, value, fill, label) => {
      const height = (value / 1900) * 200;
      return [f.rect(x - 22, 300 - height, 44, height, { r: 5, fill }), f.text(x, 292 - height, value.toFixed(0), { size: 12, weight: 600 }), f.text(x, 318, label, { size: 11, fill: "mid" })];
    };
    const beamBar = s.beam ? f.rect(710 - 22, 300 - (m.clockwise / 1900) * 200, 44, (m.beam / 1900) * 200, { r: 5, fill: "warm" }) : "";
    const balance = 300 - (m.anticlockwise / 1900) * 200;
    return [
      f.ground(40, 560, FLOOR),
      f.shadow(px, FLOOR + 2, 120),
      f.poly([[px, py + 2], [px - 30, FLOOR], [px + 30, FLOOR]], { fill: "ink" }),
      weight(-LEFT.arm, m.leftForce, `${m.leftForce.toFixed(0)} N`, "cool"),
      weight(s.arm, m.rightForce, `${m.rightForce.toFixed(0)} N`, "accent"),
      s.beam ? weight(BEAM.arm, m.beamForce * 2.4, `${m.beamForce.toFixed(0)} N`, "warm") : "",
      f.group(beam, { rotate: [m.tilt, px, py] }),
      f.circle(px, py, 6, { fill: "paper", stroke: "ink", width: 3 }),
      f.text(px, FLOOR + 22, "pivot", { size: 11, fill: "mid" }),
      f.rect(588, 40, 172, 300, { r: 12, fill: "paper", stroke: "lo" }),
      f.text(674, 64, "moments (N·m)", { size: 12, fill: "mid" }),
      f.line(604, 300, 744, 300, { stroke: "mid", width: 1.2 }),
      bar(638, m.anticlockwise, "cool", "anticlockwise"),
      bar(710, m.clockwise, "accent", "clockwise"),
      beamBar,
      f.line(604, balance, 744, balance, { stroke: m.level ? "good" : "lo", width: 1.4, dash: "4 4" }),
    ];
  },
});

